export const findSpell = (id: string) => SPELLS.find(sp => sp.id === id)

/** Spells på én eller flere klasselister med netop dette spell-level. */
export const spellsFor = (classIds: string | string[], level: SpellLevel) => {
  const ids = Array.isArray(classIds) ? classIds : [classIds]
  return SPELLS.filter(sp => sp.level === level && sp.classes.some(c => ids.includes(c))).map(sp => sp.id)
}

/** Spells på klasselisterne fra level 1 op til og med `maxLevel` (ingen cantrips). */
export const spellsUpTo = (classIds: string | string[], maxLevel: number) => {
  const ids = Array.isArray(classIds) ? classIds : [classIds]
  return SPELLS.filter(sp => sp.level >= 1 && sp.level <= maxLevel && sp.classes.some(c => ids.includes(c))).map(sp => sp.id)
}
